require 'digest'
require 'securerandom'
require 'json'
require 'redis'
require 'time'

module DistributedCache
  class AuthTokenManager
    ROTATION_INTERVAL = 300 # 5 minutes
    TOKEN_NAMESPACE = "auth:tokens:"
    NONCE_NAMESPACE = "auth:nonces:"

    def initialize(redis_url:, service_name:, shared_secret:)
      @redis = Redis.new(url: redis_url)
      @service_name = service_name
      @shared_secret = shared_secret
      @local_cache = {}
      @cache_mutex = Mutex.new
    end

    def generate_auth_token(target_service:, operation:, resource_key:)
      timestamp = Time.now.to_i
      nonce = SecureRandom.hex(16)

      token_data = {
        issuer: @service_name,
        target: target_service,
        operation: operation,
        resource: resource_key,
        timestamp: timestamp,
        nonce: nonce
      }

      signature = compute_signature(token_data)
      token_data[:signature] = signature

      store_nonce(nonce, timestamp)
      token_data
    end

    def validate_and_execute(token_data, &block)
      return { error: "invalid_token" } unless valid_structure?(token_data)
      return { error: "expired" } if token_expired?(token_data[:timestamp])
      return { error: "invalid_signature" } unless valid_signature?(token_data)

      # Check-then-act: validate nonce hasn't been used, then mark as used
      nonce_key = "#{NONCE_NAMESPACE}#{token_data[:nonce]}"

      # Read current nonce state
      nonce_state = @redis.get(nonce_key)

      if nonce_state == "consumed"
        return { error: "replay_detected" }
      end

      # Perform the authorized operation
      result = execute_cached_operation(token_data, &block)

      # Mark nonce as consumed after execution
      @redis.set(nonce_key, "consumed", ex: ROTATION_INTERVAL * 2)

      result
    end

    def cached_read(key, token_data)
      validate_and_execute(token_data) do
        cache_key = build_cache_key(token_data[:target], key)
        value = @redis.get(cache_key)
        value ? JSON.parse(value) : nil
      end
    end

    def cached_write(key, value, token_data, ttl: 3600)
      validate_and_execute(token_data) do
        cache_key = build_cache_key(token_data[:target], key)
        @redis.set(cache_key, JSON.generate(value), ex: ttl)
        { written: true, key: key }
      end
    end

    def cached_delete(key, token_data)
      validate_and_execute(token_data) do
        cache_key = build_cache_key(token_data[:target], key)
        @redis.del(cache_key)
        { deleted: true, key: key }
      end
    end

    def invalidate_service_cache(target_service, token_data)
      validate_and_execute(token_data) do
        pattern = "cache:#{target_service}:*"
        keys = @redis.keys(pattern)
        @redis.del(*keys) unless keys.empty?
        { invalidated: keys.length }
      end
    end

    private

    def execute_cached_operation(token_data)
      resource = token_data[:resource]
      operation = token_data[:operation]

      unless authorized_operation?(token_data[:issuer], operation, resource)
        return { error: "unauthorized_operation" }
      end

      yield
    end

    def authorized_operation?(issuer, operation, resource)
      # Service-level ACL check
      acl_key = "acl:#{issuer}:#{operation}"
      @redis.sismember(acl_key, resource) || @redis.sismember(acl_key, "*")
    end

    def compute_signature(token_data)
      payload = [
        token_data[:issuer],
        token_data[:target],
        token_data[:operation],
        token_data[:resource],
        token_data[:timestamp].to_s,
        token_data[:nonce]
      ].join("|")

      OpenSSL::HMAC.hexdigest("SHA256", @shared_secret, payload)
    end

    def valid_signature?(token_data)
      expected = compute_signature(token_data)
      secure_compare(expected, token_data[:signature])
    end

    def secure_compare(a, b)
      return false unless a.bytesize == b.bytesize
      l = a.unpack("C*")
      r = b.unpack("C*")
      result = 0
      l.zip(r) { |x, y| result |= x ^ y }
      result == 0
    end

    def valid_structure?(token_data)
      required = [:issuer, :target, :operation, :resource, :timestamp, :nonce, :signature]
      required.all? { |k| token_data.key?(k) }
    end

    def token_expired?(timestamp)
      (Time.now.to_i - timestamp).abs > ROTATION_INTERVAL
    end

    def store_nonce(nonce, timestamp)
      nonce_key = "#{NONCE_NAMESPACE}#{nonce}"
      @redis.set(nonce_key, "issued:#{timestamp}", ex: ROTATION_INTERVAL * 2)
    end

    def build_cache_key(service, key)
      "cache:#{service}:#{key}"
    end
  end
end
